def build():
    checkpoint={'schema_version':1,'status':'explicit_fourth_batch','tracks':{}}
    base=json.loads((ROOT/'tools'/'curriculum.json').read_text(encoding='utf-8'))
    for tool,text in SPECS.items():
        prior=[]
        for suffix in ['', '-batch2','-batch3']:
            p=BANK/f'{tool}{suffix}.json'
            if p.exists():prior+=json.loads(p.read_text(encoding='utf-8'))
        known={p['id'] for p in base['problems']}|{p['id'] for p in prior}
        rows=[line.split('|') for line in text.strip().splitlines()]
        assert all(len(row)==7 for row in rows),(tool,'invalid field separator')
        rows.sort(key=lambda row:int(row[0]))
        path=BANK/f'{tool}-batch4.json'
        existing=json.loads(path.read_text(encoding='utf-8')) if path.exists() else []
        old_by_title={p['title']:p for p in existing}
        assert set(old_by_title)<={r[1] for r in rows},'published title removal refused'
        next_number=max([int(p['id'].rsplit('-',1)[1]) for p in existing]+[START[tool]-1])+1
        prefix='DELTA-LAKE' if tool=='delta-lake' else tool.upper()
        level_prev={};problems=[]
        for lev,title,task,fixture,result,boundary,hint in rows:
            level=int(lev);old=old_by_title.get(title)
            if old:pid=old['id']
            else:pid=f'RLP-{prefix}-{next_number:03}';next_number+=1
            candidates=sorted([p for p in prior if p['level']<=level],key=lambda p:(p['level'],p.get('sequence',int(p['id'].rsplit('-',1)[1]))))
            previous=level_prev.get(level,candidates[-1]['id']);level_prev[level]=pid
            assert previous in known,(pid,previous)
            hints=hints_for(tool,title,result);hints[2]=hint
            problems.append({'id':pid,'tool_id':tool,'title':title,'level':level,'prerequisites':old['prerequisites'] if old else [previous],
                'scenario':task,'task':task,'learning_objective':title,
                'inputs':{'fixture':fixture,'environment':'Existing compatible local or authorized cloud training environment; isolated synthetic artifacts; record runtime and actual observations.'},
                'expected_output':{'observed_behavior':result},
                'constraints':['Preserve raw sources,learner attempts and accepted historical evidence. Use only the bounded synthetic fixture and isolated outputs.',
                    'No production mutation,new paid resource provisioning,credential disclosure or external notifications to people.',
                    'Verify capability/protocol compatibility before a feature change. Unsupported or inaccessible execution is environment_blocked,not passed; plans/simulations do not prove cloud execution.'],
                'acceptance_criteria':[result,'Demonstrate the additional boundary: '+boundary,'Submit implementation/configuration,actual observed results and assistance disclosure for independent review.'],
                'estimated_minutes':20 if level<4 else 35 if level<6 else 50 if level<8 else 75 if level<10 else 120,
                'engineering_relevance':f'{title} protects a real storage,processing or operational contract. After review,explain its downstream consequence and one limitation of the implementation.',
                'official_docs':[DOCS[tool],EXTRA_DOCS[tool]],'verification':{'kind':'artifact_review'},'topic_id':None,
                'published_version':'2026.10.26.4','independent_prerequisites':[],'difficulty':f'level_{level}',
                'challenge_kind':'transfer' if level==10 else 'bridge' if not any(x['level']==level for x in problems) else 'initial',
                'skill_prerequisites':['Verified prerequisite implementation evidence or a reviewer-approved exact-skill diagnostic.'],
                'progressive_hints':hints,'sequence':int(pid.rsplit('-',1)[1]),'authoring_batch':'cloud-explicit-004',
                'followup':{'task':'Independently reconstruct the bounded implementation using the changed-input check; explain observed behavior and disclose help.',
                    'inputs':{'base_fixture':fixture,'changed_input_check':boundary},'expected_output':{'contract':boundary},
                    'verification':{'kind':'artifact_review'},'constraints':['Keep the previous solution closed and preserve the independent attempt and actual outputs.']}})
            known.add(pid)
        assert len({p['id'] for p in problems})==len(problems)
        assert len({p['title'] for p in problems})==len(problems)
        assert len({p['task'] for p in problems})==len(problems)
        assert not {p['task'] for p in problems}&{p['task'] for p in prior}
        total=1+len(prior)+len(problems)
        assert total<=TARGETS[tool],(tool,total,'target exceeded')
        path.write_text(json.dumps(problems,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        checkpoint['tracks'][tool]={'target':TARGETS[tool],'preserved_previous_additions':len(prior),'batch4_additions':len(problems),'prepared_total_including_seed':total,
            'remaining':TARGETS[tool]-total,'next_id':f'RLP-{prefix}-{next_number:03}',
            'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
            'next_action':'Continue explicit distinct capability authoring if target remains; never multiply generic modes.'}
    (BANK/'authors'/'cloud-batch4-checkpoint.json').write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(checkpoint,indent=2))

if __name__=='__main__':build()
